import { NextRequest, NextResponse } from 'next/server';
import { db, dbWithRetry } from '@/lib/db';
import { cache, CacheKeys, CacheTTL, invalidateUserCache } from '@/lib/cache';
import bcrypt from 'bcryptjs';
import { generateCode } from '@/utils/helpers';



export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const roleParam = searchParams.get('role');
    const noCache   = searchParams.get('noCache') === 'true';

    // Generate cache key
    const cacheKey = roleParam ? CacheKeys.usersByRole(roleParam) : CacheKeys.usersList();

    // Check cache first (skip if noCache requested)
    if (!noCache) {
      const cachedUsers = cache.get(cacheKey);
      if (cachedUsers) {
        return NextResponse.json({ users: cachedUsers, cached: true });
      }
    }

    // Build where clause properly
    let where: any = {};
    
    if (roleParam) {
      const roles = roleParam.split(',').map(r => r.trim()).filter(Boolean);
      if (roles.length === 1) {
        where = { role: roles[0] };
      } else if (roles.length > 1) {
        where = { role: { in: roles } };
      }
    }

    const users = await db.user.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        name: true,
        email: true,
        phone: true,
        role: true,
        isActive: true,
        isLocked: true,
        createdAt: true,
        companyId: true,
        agentId: true,
        agentCode: true,
        staffCode: true,
        cashierCode: true,
        accountantCode: true,
        companyCredit: true,
        personalCredit: true,
        credit: true,
        profilePicture: true,
        company: { 
          select: { id: true, name: true, code: true, isMirrorCompany: true } 
        },
        agent: { 
          select: { id: true, name: true, agentCode: true } 
        }
      }
    });

    // Cache the result
    cache.set(cacheKey, users, CacheTTL.MEDIUM);

    return NextResponse.json({ users });
  } catch (error) {
    console.error('Error fetching users:', error);
    return NextResponse.json({ error: 'Failed to fetch users', details: error instanceof Error ? error.message : 'Unknown error' }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { 
      name, email, phone, password, role, companyId, agentId,
      // Extended company fields
      code, address, city, state, pincode, gstNumber, panNumber, website,
      ownerName, ownerPhone, ownerEmail, ownerPan, ownerAadhaar, logoUrl,
      isMirrorCompany, mirrorInterestRate, mirrorInterestType,
      accountingType, defaultInterestRate, defaultInterestType
    } = body;

    // Convert empty strings to null for foreign key fields
    // AGENT, CASHIER, and ACCOUNTANT are common for all companies - no company selection needed
    const rolesWithoutCompany = ['AGENT', 'CASHIER', 'ACCOUNTANT'];
    const cleanCompanyId = rolesWithoutCompany.includes(role) ? null : (companyId && companyId.trim() !== '' ? companyId : null);
    const cleanAgentId = agentId && agentId.trim() !== '' ? agentId : null;

    if (!name || !email || !password || !role) {
      return NextResponse.json({ error: 'Missing required fields: name, email, password, role' }, { status: 400 });
    }

    // Wrap in dbWithRetry so transient Prisma warmup panics are retried
    const existingUser = await dbWithRetry(() => db.user.findUnique({ where: { email } }));

    if (existingUser) {
      return NextResponse.json({ error: 'User with this email already exists' }, { status: 400 });
    }

    const hashedPassword = await bcrypt.hash(password, 10);
    const firebaseUid = `email-${Date.now()}`;

    let userCompanyId = cleanCompanyId;
    let createdCompany: Awaited<ReturnType<typeof db.company.create>> | null = null;

    // Create company if role is COMPANY and no company specified
    if (role === 'COMPANY' && !cleanCompanyId) {
      // Use user-provided code OR generate unique code
      let companyCode: string;
      
      if (code && code.trim()) {
        companyCode = code.trim().toUpperCase();
        const existingCompany = await db.company.findUnique({ where: { code: companyCode } });
        if (existingCompany) {
          return NextResponse.json({ error: `Company code "${companyCode}" already exists. Please use a different code.`, field: 'code' }, { status: 400 });
        }
      } else {
        companyCode = generateCode('COMP');
        for (let i = 0; i < 5; i++) {
          const exists = await db.company.findUnique({ where: { code: companyCode } });
          if (!exists) break;
          companyCode = i < 4 ? generateCode('COMP') : `COMP${Date.now()}${Math.random().toString(36).substring(2,8).toUpperCase()}`;
        }
      }
      
      try {
        createdCompany = await dbWithRetry(() => db.company.create({
          data: {
            name,
            code: companyCode,
            contactEmail: email,
            contactPhone: phone || null,
            address: address || null,
            city: city || null,
            state: state || null,
            pincode: pincode || null,
            gstNumber: gstNumber || null,
            panNumber: panNumber || null,
            website: website || null,
            ownerName: ownerName || null,
            ownerPhone: ownerPhone || null,
            ownerEmail: ownerEmail || null,
            ownerPan: ownerPan || null,
            ownerAadhaar: ownerAadhaar || null,
            logoUrl: logoUrl || null,
            isMirrorCompany: isMirrorCompany !== undefined ? isMirrorCompany : true,
            mirrorInterestRate: mirrorInterestRate ?? null,
            mirrorInterestType: mirrorInterestType || 'REDUCING',
            accountingType: accountingType || 'FULL',
            defaultInterestRate: defaultInterestRate || 12,
            defaultInterestType: defaultInterestType || 'FLAT',
            isActive: true
          }
        }));
        userCompanyId = createdCompany.id;
        // Initialize chart of accounts so accounting portal works immediately
        try {
          const { AccountingService } = await import('@/lib/accounting-service');
          const accountingService = new AccountingService(createdCompany.id);
          await accountingService.initializeChartOfAccounts();
        } catch { /* non-fatal — company still created */ }
      } catch (companyError) {
        if (companyError instanceof Error &&
            (companyError.message.includes('Unique constraint') || companyError.message.includes('code'))) {
          return NextResponse.json({ error: 'Company code already exists. Please try again.' }, { status: 400 });
        }
        throw companyError;
      }
    }

    // Validate that company exists if companyId is provided (not for roles that are ecosystem-wide)
    const ecosystemWideRoles = ['AGENT', 'CASHIER', 'ACCOUNTANT'];
    if (userCompanyId && role !== 'COMPANY' && !ecosystemWideRoles.includes(role)) {
      const companyExists = await dbWithRetry(() => db.company.findUnique({
        where: { id: userCompanyId }
      }));
      if (!companyExists) {
        return NextResponse.json({ error: 'Selected company does not exist' }, { status: 400 });
      }
    }

    // Validate that agent exists if agentId is provided
    if (cleanAgentId && role === 'STAFF') {
      const agentExists = await dbWithRetry(() => db.user.findFirst({
        where: { id: cleanAgentId, role: 'AGENT' }
      }));
      if (!agentExists) {
        return NextResponse.json({ error: 'Selected agent does not exist' }, { status: 400 });
      }
    }

    const roleCodes: Record<string, string> = {
      AGENT: generateCode('AG'),
      STAFF: generateCode('ST'),
      CASHIER: generateCode('CS'),
      ACCOUNTANT: generateCode('ACC')
    };

    
    let user;
    try {
      user = await dbWithRetry(() => db.user.create({
        data: {
          name,
          email,
          phone: phone || null,
          password: hashedPassword,
          plainPassword: password,
          firebaseUid,
          role: role,
          companyId: userCompanyId,
          agentId: role === 'STAFF' ? cleanAgentId : null,
          agentCode: role === 'AGENT' ? roleCodes.AGENT : null,
          staffCode: role === 'STAFF' ? roleCodes.STAFF : null,
          cashierCode: role === 'CASHIER' ? roleCodes.CASHIER : null,
          accountantCode: role === 'ACCOUNTANT' ? roleCodes.ACCOUNTANT : null,
          // Commission removed - no one takes commission in this system
          commissionRate: 0,
          lastLoginAt: new Date()
        },
        include: {
          company: true,
          agent: true
        }
      }));
    } catch (userCreateError) {
      // CLEANUP: If user creation failed (e.g. timeout, DB panic, unique constraint on email)
      // but we successfully created a Company above, we MUST delete that orphaned company
      // so the user can safely retry without hitting "Company code already exists".
      if (createdCompany && createdCompany.id) {
        try {
          console.log(`[User API] User creation failed, rolling back orphaned company: ${createdCompany.id}`);
          // Delete accounting data first if any
          await db.chartOfAccount.deleteMany({ where: { companyId: createdCompany.id } });
          await db.company.delete({ where: { id: createdCompany.id } });
        } catch (rollbackError) {
          console.error('[User API] Failed to rollback orphaned company:', rollbackError);
        }
      }

      if (userCreateError instanceof Error) {
        if (userCreateError.message.includes('Unique constraint'))
          return NextResponse.json({ error: 'Email already exists. Please use a different email.' }, { status: 400 });
        if (userCreateError.message.includes('foreign key'))
          return NextResponse.json({ error: 'Invalid company or agent reference.' }, { status: 400 });
      }
      throw userCreateError;
    }


    await db.auditLog.create({
      data: {
        userId: user.id,
        action: 'CREATE',
        module: 'USER',
        description: `User created with role ${role}`,
        recordId: user.id,
        recordType: 'User',
        ipAddress: request.headers.get('x-forwarded-for') || 'unknown'
      }
    });

    // Invalidate user cache
    invalidateUserCache();

    return NextResponse.json({
      success: true,
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        companyId: user.companyId,
        company: user.company,
        agentCode: user.agentCode,
        staffCode: user.staffCode,
        cashierCode: user.cashierCode,
        accountantCode: user.accountantCode
      }
    });
  } catch (error) {
    console.error('[User API] Error creating user:', error);
    // Log full error details for debugging
    if (error instanceof Error) {
      console.error('[User API] Error name:', error.name);
      console.error('[User API] Error message:', error.message);
      console.error('[User API] Error stack:', error.stack);
    }
    return NextResponse.json({ 
      error: 'Failed to create user', 
      details: error instanceof Error ? error.message : 'Unknown error',
      errorType: error instanceof Error ? error.name : 'Unknown'
    }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  try {
    const body = await request.json();
    const { id, name, phone, isActive, agentId } = body;

    if (!id) {
      return NextResponse.json({ error: 'User ID is required' }, { status: 400 });
    }

    // Protect permanent super admin from being deactivated
    const PERMANENT_SUPER_ADMIN_EMAILS = ['moneymitra@gmail.com'];
    if (isActive === false) {
      const user = await db.user.findUnique({ where: { id } });
      if (user && PERMANENT_SUPER_ADMIN_EMAILS.includes(user.email)) {
        return NextResponse.json({ 
          error: 'Cannot deactivate the permanent Super Admin account. This account is protected.',
          isProtected: true 
        }, { status: 403 });
      }
    }

    const updateData: Record<string, unknown> = {};
    if (name !== undefined) updateData.name = name;
    if (phone !== undefined) updateData.phone = phone;
    if (isActive !== undefined) updateData.isActive = isActive;
    if (agentId !== undefined) updateData.agentId = agentId;

    const user = await db.user.update({
      where: { id },
      data: updateData,
      include: { company: true, agent: true }
    });

    // Invalidate user cache
    invalidateUserCache(id);

    return NextResponse.json({ success: true, user });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to update user' }, { status: 500 });
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) return NextResponse.json({ error: 'User ID is required' }, { status: 400 });

    const user = await db.user.findUnique({ where: { id } });
    if (!user) return NextResponse.json({ error: 'User not found' }, { status: 404 });

    const PERMANENT_SUPER_ADMIN_EMAILS = ['moneymitra@gmail.com'];
    if (PERMANENT_SUPER_ADMIN_EMAILS.includes(user.email)) {
      return NextResponse.json({ error: 'Cannot delete the permanent Super Admin account.', isProtected: true }, { status: 403 });
    }

    const [loanApplications, sessionForms, payments] = await Promise.all([
      db.loanApplication.count({ where: { customerId: id } }),
      db.sessionForm.count({ where: { agentId: id } }),
      db.payment.count({ where: { customerId: id } }),
    ]);

    if (loanApplications > 0 || sessionForms > 0 || payments > 0) {
      const relatedInfo: string[] = [];
      if (loanApplications > 0) relatedInfo.push(`${loanApplications} loan application(s)`);
      if (sessionForms > 0) relatedInfo.push(`${sessionForms} session form(s)`);
      if (payments > 0) relatedInfo.push(`${payments} payment(s)`);
      return NextResponse.json({ error: `Cannot delete user. They have: ${relatedInfo.join(', ')}.`, hasRelations: true }, { status: 400 });
    }

    await Promise.all([
      db.auditLog.deleteMany({ where: { userId: id } }),
      db.notification.deleteMany({ where: { userId: id } }),
      db.workflowLog.deleteMany({ where: { actionById: id } }),
      db.locationLog.deleteMany({ where: { userId: id } }),
      db.reminder.deleteMany({ where: { userId: id } }),
      db.notificationSetting.deleteMany({ where: { userId: id } }),
      db.deviceFingerprint.deleteMany({ where: { userId: id } }),
      db.blacklist.deleteMany({ where: { userId: id } }),
    ]);

    await db.user.delete({ where: { id } });

    // If this was a COMPANY user, also delete the orphaned Company record
    // (prevents 'Company code already exists' when re-creating with same code)
    if (user.role === 'COMPANY' && user.companyId) {
      try {
        await Promise.all([
          db.ledgerBalance.deleteMany({ where: { account: { companyId: user.companyId } } }),
          db.journalEntryLine.deleteMany({ where: { account: { companyId: user.companyId } } }),
          db.chartOfAccount.deleteMany({ where: { companyId: user.companyId } }),
          db.journalEntry.deleteMany({ where: { companyId: user.companyId } }),
          db.ledgerBalance.deleteMany({ where: { financialYear: { companyId: user.companyId } } }),
          db.financialYear.deleteMany({ where: { companyId: user.companyId } }),
          db.bankAccount.deleteMany({ where: { companyId: user.companyId } }),
          db.ledger.deleteMany({ where: { companyId: user.companyId } }),
          db.expense.deleteMany({ where: { companyId: user.companyId } }),
          db.gSTConfig.deleteMany({ where: { companyId: user.companyId } }),
          db.commissionSlab.deleteMany({ where: { companyId: user.companyId } }),
          db.gracePeriodConfig.deleteMany({ where: { companyId: user.companyId } }),
          db.preApprovedOffer.deleteMany({ where: { companyId: user.companyId } }),
          db.agentPerformance.deleteMany({ where: { companyId: user.companyId } }),
        ]);
        await db.company.delete({ where: { id: user.companyId } }).catch(() => {/* already deleted */});
      } catch { /* non-fatal */ }
    }

    invalidateUserCache(id);
    cache.deletePattern('companies:');
    cache.deletePattern('users:');

    return NextResponse.json({ success: true, message: 'User permanently deleted', deletedUserId: id });
  } catch (error) {
    console.error('[User DELETE] Error deleting user:', error);
    
    // Handle Prisma foreign key constraint errors
    if (error instanceof Error && error.message.includes('Foreign key constraint failed')) {
      return NextResponse.json({ 
        error: 'Cannot delete user. They have related records in the system. Please remove or reassign these records first.' 
      }, { status: 400 });
    }
    
    return NextResponse.json({ 
      error: 'Failed to delete user',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}
